using System.Text.Json;
using System.Text.Json.Nodes;

namespace Trail.UnitTests.Api;

/// <summary>
/// Guards the committed OpenAPI document (<c>web/openapi/Trail.Api.json</c>) that the web client's types are generated
/// from. Endpoints return <c>IResult</c>, so a forgotten <c>.Returns&lt;T&gt;()</c> silently produces a response with
/// no schema. The file is regenerated by building <c>src/Trail.Api</c> in Debug (<c>dotnet build src/Trail.Api</c>);
/// CI fails when the committed copy is stale.
/// </summary>
public class OpenApiDocumentTests
{
    private static readonly string[] Methods = ["get", "put", "post", "delete", "patch"];

    /// <summary>Operations ("GET /api/v1/x") whose 200/201 response legitimately has no JSON schema. Keep this empty if possible.</summary>
    private static readonly HashSet<string> WithoutSchema = [];

    private static JsonObject Load()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "Trail.slnx")))
            directory = directory.Parent;

        directory.ShouldNotBeNull("Could not locate the repository root (Trail.slnx).");
        var path = Path.Combine(directory.FullName, "web", "openapi", "Trail.Api.json");
        File.Exists(path).ShouldBeTrue($"{path} is missing. Run: dotnet build src/Trail.Api");
        return JsonNode.Parse(File.ReadAllText(path))!.AsObject();
    }

    private static IEnumerable<(string Name, JsonObject Operation)> Operations(JsonObject document) =>
        from path in document["paths"]!.AsObject()
        from method in Methods
        where path.Value!.AsObject().ContainsKey(method)
        select ($"{method.ToUpperInvariant()} {path.Key}", path.Value!.AsObject()[method]!.AsObject());

    [Fact]
    public void Successful_responses_declare_a_schema()
    {
        var missing = new List<string>();
        foreach (var (name, operation) in Operations(Load()))
        {
            foreach (var (status, response) in operation["responses"]!.AsObject())
            {
                if (status is not ("200" or "201") || WithoutSchema.Contains(name)) continue;

                var schema = response?["content"]?.AsObject().FirstOrDefault().Value?["schema"];
                if (schema is null) missing.Add($"{name} -> {status}");
            }
        }

        missing.ShouldBeEmpty("Add .Returns<T>() / .Creates<T>() to these endpoints, then rebuild src/Trail.Api.");
    }

    [Fact]
    public void Operation_ids_are_present_and_unique()
    {
        var ids = Operations(Load()).Select(o => o.Operation["operationId"]?.GetValue<string>()).ToList();

        ids.ShouldAllBe(id => !string.IsNullOrEmpty(id));
        ids.Distinct().Count().ShouldBe(ids.Count);
    }

    [Fact]
    public void Enums_are_strings_and_document_is_titled()
    {
        var document = Load();

        document["info"]!["title"]!.GetValue<string>().ShouldBe("Trail API");
        var schemas = document["components"]!["schemas"]!.AsObject();
        schemas["AttachmentKind"]!["enum"]!.AsArray().ShouldAllBe(v => v!.GetValueKind() == JsonValueKind.String);
    }
}